begin;set local search_path=public,extensions;select plan(11);
select ok((select p.prosecdef and p.proconfig::text like '%search_path=pg_catalog%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_catalog_questionnaire'),'create questionnaire RPC fixes its security path');
select ok(not has_function_privilege('anon','public.create_catalog_questionnaire(uuid,uuid,text,jsonb,text,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.create_catalog_questionnaire(uuid,uuid,text,jsonb,text,text,uuid)','EXECUTE'),'non-user roles cannot create questionnaires');
select ok(not has_table_privilege('authenticated','public.questionnaires','INSERT')and not has_table_privilege('authenticated','public.questionnaire_sections','INSERT'),'direct questionnaire writes stay denied');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('fa100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-questionnaire-admin@example.invalid','',now(),'{}','{}',now(),now()),('fa100000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-questionnaire-outsider@example.invalid','',now(),'{}','{}',now(),now());
insert into public.platform_user_roles(user_id,role_code)values('fa100000-0000-0000-0000-000000000001','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('fa110000-0000-0000-0000-000000000001','P06 Questionnaire Steward','P06 Questionnaire Steward','ACTIVE','fa100000-0000-0000-0000-000000000001');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,status,created_by)values('fa120000-0000-0000-0000-000000000001','P06_FORM','p06-form','fa110000-0000-0000-0000-000000000001','DRAFT','fa100000-0000-0000-0000-000000000001');
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,created_by)values('fa130000-0000-0000-0000-000000000001','fa120000-0000-0000-0000-000000000001','P06.FORM.V1','DRAFT',repeat('a',64),'fa100000-0000-0000-0000-000000000001');
create temporary table p06_form_payload(value jsonb);create temporary table p06_form_observed(key text primary key,value jsonb);insert into p06_form_payload values('{"title_fr":"Diagnostic sécurité","title_ar":"تشخيص الأمان","description_fr":"Questionnaire initial de sécurité","description_ar":"استبيان الأمان الأولي","audience":"CLIENT","engine_version":"1.0.0","policy_version":"P06-1","sensitive":false,"section_key":"GENERAL","section_label_fr":"Général","section_label_ar":"عام","section_help_fr":"Informations générales","section_help_ar":"معلومات عامة"}'::jsonb);grant select on p06_form_payload to authenticated;grant select,insert on p06_form_observed to authenticated;grant usage on schema extensions to authenticated;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"fa100000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);select throws_ok($$select public.create_catalog_questionnaire('fa120000-0000-0000-0000-000000000001','fa130000-0000-0000-0000-000000000001','SECURITY',(select value from p06_form_payload),'Création refusée','form-hidden')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','outsider cannot infer or create questionnaire content');
select set_config('request.jwt.claims','{"sub":"fa100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);insert into p06_form_observed values('created',public.create_catalog_questionnaire('fa120000-0000-0000-0000-000000000001','fa130000-0000-0000-0000-000000000001','SECURITY',(select value from p06_form_payload),'Création questionnaire','form-create-0001','fa160000-0000-0000-0000-000000000001'));insert into p06_form_observed values('replay',public.create_catalog_questionnaire('fa120000-0000-0000-0000-000000000001','fa130000-0000-0000-0000-000000000001','SECURITY',(select value from p06_form_payload),'Création questionnaire','form-create-0001','fa160000-0000-0000-0000-000000000099'));reset role;
select is((select value from p06_form_observed where key='created'),(select value from p06_form_observed where key='replay'),'retry returns durable response');
select is((select value->>'outcome'from p06_form_observed where key='created'),'CATALOG_QUESTIONNAIRE_CREATED','typed outcome is returned');
select ok((select status='DRAFT'and current_draft_version_id=(select(value->>'version_id')::uuid from p06_form_observed where key='created')from public.questionnaires where id=(select(value->>'questionnaire_id')::uuid from p06_form_observed where key='created')),'identity points to draft version one');
select ok((select title_ar='تشخيص الأمان'and audience='CLIENT'and translation_review_status='PENDING'and snapshot_hash~'^[0-9a-f]{64}$'from public.questionnaire_versions where id=(select(value->>'version_id')::uuid from p06_form_observed where key='created')),'version persists bilingual governed metadata');
select ok((select section_key='GENERAL'and label_ar='عام'and sort_order=1 and content_hash~'^[0-9a-f]{64}$'from public.questionnaire_sections where id=(select(value->>'section_id')::uuid from p06_form_observed where key='created')),'first immutable section is materialized');
select ok((select count(*)=1 from public.audit_events where action='catalog.questionnaire.created'and resource_id=(select value->>'questionnaire_id'from p06_form_observed where key='created'))and(select count(*)=1 from public.event_outbox where event_type='CatalogQuestionnaireCreatedV1'and aggregate_id=(select value->>'questionnaire_id'from p06_form_observed where key='created')),'creation emits one audit and one safe Outbox event');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"fa100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);select throws_ok($$select public.create_catalog_questionnaire('fa120000-0000-0000-0000-000000000001','fa130000-0000-0000-0000-000000000001','SENSITIVE',(select value||'{"sensitive":true}'::jsonb from p06_form_payload),'Questionnaire sensible','form-sensitive-0001')$$,'42501'::char(5),'CATALOG_SENSITIVE_MFA_REQUIRED','sensitive questionnaire authoring requires AAL2');reset role;
select * from finish();rollback;
